<?php require '../config/database.php';auth();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM repairs WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)die('الطلب غير موجود');$techs=$pdo->query("SELECT id,name FROM technicians WHERE status='active'")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$status=$_POST['status'];$del=$status==='delivered'?date('Y-m-d H:i:s'):null;$s=$pdo->prepare('UPDATE repairs SET technician_id=?,device_type=?,device_model=?,serial_number=?,problem=?,diagnosis=?,repair_notes=?,status=?,estimated_cost=?,final_cost=?,paid_amount=?,delivered_at=? WHERE id=?');$s->execute([$_POST['technician_id']?:null,$_POST['device_type'],$_POST['device_model'],$_POST['serial_number'],$_POST['problem'],$_POST['diagnosis'],$_POST['repair_notes'],$status,(float)$_POST['estimated_cost'],(float)$_POST['final_cost'],(float)$_POST['paid_amount'],$del,$id]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تعديل طلب الصيانة</h1><form method="post"><label>الفني</label><select name="technician_id"><option value="">غير محدد</option><?php foreach($techs as $t):?><option value="<?=$t['id']?>" <?=$r['technician_id']==$t['id']?'selected':''?>><?=htmlspecialchars($t['name'])?></option><?php endforeach;?></select><label>نوع الجهاز</label><input name="device_type" value="<?=htmlspecialchars($r['device_type'])?>"><label>الموديل</label><input name="device_model" value="<?=htmlspecialchars($r['device_model'])?>"><label>الرقم التسلسلي</label><input name="serial_number" value="<?=htmlspecialchars($r['serial_number'])?>"><label>المشكلة</label><textarea name="problem"><?=htmlspecialchars($r['problem'])?></textarea><label>التشخيص</label><textarea name="diagnosis"><?=htmlspecialchars($r['diagnosis'])?></textarea><label>ملاحظات الإصلاح</label><textarea name="repair_notes"><?=htmlspecialchars($r['repair_notes'])?></textarea><label>الحالة</label><select name="status"><?php foreach(['new'=>'جديد','checking'=>'قيد الفحص','repairing'=>'قيد الصيانة','ready'=>'جاهز','delivered'=>'تم التسليم','cancelled'=>'ملغي'] as $k=>$v):?><option value="<?=$k?>" <?=$r['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><label>التكلفة المتوقعة</label><input type="number" step="0.01" name="estimated_cost" value="<?=$r['estimated_cost']?>"><label>التكلفة النهائية</label><input type="number" step="0.01" name="final_cost" value="<?=$r['final_cost']?>"><label>المدفوع</label><input type="number" step="0.01" name="paid_amount" value="<?=$r['paid_amount']?>"><button>حفظ</button></form></main>
